gold.schema_ddl:
CREATE TABLE corrieri (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    telefono TEXT,
    citta TEXT NOT NULL
);

CREATE TABLE indirizzi (
    id SERIAL PRIMARY KEY,
    via TEXT NOT NULL,
    citta TEXT NOT NULL,
    cap TEXT NOT NULL
);

CREATE TABLE pacchi (
    id SERIAL PRIMARY KEY,
    corriere_id INT NOT NULL REFERENCES corrieri(id),
    indirizzo_id INT NOT NULL REFERENCES indirizzi(id),
    peso NUMERIC(8,2) CHECK (peso > 0),
    descrizione TEXT,
    cap TEXT NOT NULL,
    citta TEXT NOT NULL
);

CREATE TABLE stati_pacco (
    id SERIAL PRIMARY KEY,
    pacchetto_id INT NOT NULL REFERENCES pacchi(id),
    stato TEXT NOT NULL,
    data_aggiornamento TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE tipi_pacco (
    id SERIAL PRIMARY KEY,
    pacchetto_id INT NOT NULL REFERENCES pacchi(id),
    tipo TEXT NOT NULL,
    peso_lordo NUMERIC(8,2) CHECK (peso_lordo >= 0)
);
